package org.springframework.samples.petclinic.rest.error;

/**
 * Thrown when a submitted email address is present but not a syntactically valid address. Carries
 * the originally submitted value so the REST layer can report what was rejected.
 */
public class InvalidEmailException extends RuntimeException {

    private final String rejectedValue;

    public InvalidEmailException(String rejectedValue) {
        super("Email must be a syntactically valid address, but was: " + rejectedValue);
        this.rejectedValue = rejectedValue;
    }

    public String getRejectedValue() {
        return this.rejectedValue;
    }
}

